INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (1, 1, 10, 'Taylor Swift a reusit sa surprinda perfect anxietatea generatiei Z. Versurile sunt brutale si oneste!', TO_DATE('2022-11-15', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (2, 1, 9, 'Cea mai vulnerabila piesa a lui Taylor. Ma regasesc complet in versuri.', TO_DATE('2022-12-01', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (1, 2, 7, 'Hit absolut, dar dupa atatia ani de ascultat devine repetitiv. Ed Sheeran stie sa faca melodii catchy.', TO_DATE('2023-02-14', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (4, 2, 9, 'Una dintre cele mai bune piese pop din ultimii ani! Nu ma satur sa o ascult.', TO_DATE('2023-03-05', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (1, 4, 8, 'Drake la cel mai bun nivel! Beat-ul este hipnotizant si flow-ul perfect.', TO_DATE('2018-02-15', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (2, 5, 10, 'Adele s-a intors in forta! Vocea ei incredibila ma face sa plang de fiecare data.', TO_DATE('2021-11-01', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (4, 5, 9, 'Emotionanta si puternica. Pianul si vocea se completeaza perfect.', TO_DATE('2021-11-20', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (1, 6, 10, 'The Weeknd a creat un masterpiece retro-futurist! Synthwave-ul perfect pentru 2020.', TO_DATE('2020-01-15', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (5, 6, 8, 'Foarte catchy si bine produsa. Mi-aminteste de Michael Jackson.', TO_DATE('2020-03-15', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (2, 7, 9, 'Billie Eilish este intr-adevar unica! Beat-ul minimal dar foarte eficient.', TO_DATE('2019-05-10', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (4, 7, 7, 'Interesanta si diferita, dar nu pentru toata lumea. Stilul ei e foarte specific.', TO_DATE('2019-06-20', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (5, 9, 8, 'Foarte energica si motivanta. Chiar si fara Arcane este o piesa grozava.', TO_DATE('2021-12-05', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (4, 10, 8, 'Retro-disco modern si foarte bien facut. Îti ridica instant dispozitia!', TO_DATE('2020-06-30', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (3, 11, 7, 'Justin Bieber s-a maturizat mult. R&B chill si placut.', TO_DATE('2021-04-10', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (5, 11, 6, 'Decenta dar nu spectaculoasa. Am asteptari mai mari de la Bieber.', TO_DATE('2021-05-01', 'YYYY-MM-DD'));
INSERT INTO RECENZIE (ID_UTILIZATOR, ID_PIESA, SCOR, COMENTARIU, DATA_RECENZIE) VALUES (4, 13, 9, 'Nu sunt fan K-pop dar recunosc ca e foarte catchy si bine facuta.', TO_DATE('2020-10-20', 'YYYY-MM-DD'));
